import * as React from 'react'
import { cn } from '@/lib/utils'

export interface ToastProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Drives the fade/slide transition. The caller owns the state and any
   *  auto-dismiss timing -- the component never dismisses itself. */
  open: boolean
  /** Optional leading icon element (e.g. a 16px Phosphor icon). */
  icon?: React.ReactNode
  /** Optional trailing action (e.g. a small accent Button). Its presence
   *  makes the toast interactive (pointer events enabled). */
  action?: React.ReactNode
  /** When provided, renders an X dismiss button and enables pointer events. */
  onDismiss?: () => void
  /** aria-label for the dismiss button. */
  dismissLabel?: string
  /**
   * When `true`, the toast is announced immediately via `role="alert"` +
   * `aria-live="assertive"` -- use for time-sensitive or error messages.
   * Default (`false`) uses `aria-live="polite"`, which waits for the user
   * to finish their current interaction before announcing.
   */
  assertive?: boolean
  /**
   * Work is in flight. Renders the design system's spinner in place of `icon`
   * and sets `aria-busy`, the same word `ProgressBar` uses for the same state.
   *
   * The spinner is drawn from a border rather than an icon, because the
   * package ships no icon library. The LABEL carries the meaning: under
   * reduced motion the global backstop leaves the circle effectively still,
   * so a toast whose only cue is the spinner says nothing there.
   */
  busy?: boolean
  /**
   * A readout that changes as the work proceeds -- a count, a percentage --
   * rendered after the message and **hidden from assistive tech**.
   *
   * The pill is a live region, so a number ticking several times a second
   * would be read out several times a second, talking over everything else on
   * the page. Hidden, the message announces once and the readout stays a
   * visual one. Digits are tabular so the pill does not resize on every tick.
   */
  detail?: React.ReactNode
}

/**
 * Floating notification pill, fixed and centered below the app header.
 * Frosted-surface chrome (same recipe as BottomNav and the surface
 * ActionPill) so it reads as part of the header family.
 *
 * Use for app-level, out-of-flow notifications: transient state hints
 * (auto-dismissed by the caller, e.g. an armed destructive button) or
 * persistent action-carrying notices (e.g. "update available" with a
 * download button + dismiss). For context-bound inline status and error
 * boxes inside forms or settings sections, use `Notice` instead.
 *
 * Purely informational toasts (no `action`, no `onDismiss`) are
 * pointer-events-none so they never intercept clicks. Keep messages to a
 * single short sentence -- the pill shape does not suit multiline text.
 *
 * For background work that resolves on its own -- an index building, a library
 * scanning -- pass `busy` with a `detail` readout and neither an action nor a
 * dismiss: there is nothing to confirm and nothing to cancel, and a dismiss
 * would only offer to hide a fact. Staying non-interactive also keeps the pill
 * from swallowing clicks meant for what is underneath it.
 */
const Toast = React.forwardRef<HTMLDivElement, ToastProps>(
  (
    {
      open,
      icon,
      action,
      onDismiss,
      dismissLabel = 'Dismiss',
      assertive = false,
      busy = false,
      detail,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const interactive = Boolean(action || onDismiss)
    return (
      <div
        ref={ref}
        // `role="alert"` carries its own implicit assertive live region; the
        // explicit aria-live pairs with it for the screen readers that read
        // only one of the two.
        role={assertive ? 'alert' : undefined}
        aria-live={assertive ? 'assertive' : 'polite'}
        {...(busy ? { 'aria-busy': true } : {})}
        className={cn(
          'fixed left-1/2 -translate-x-1/2 z-40',
          'top-[calc(env(safe-area-inset-top)+0.75rem)] md:top-20',
          'flex items-center gap-2 px-4 py-2 rounded-full',
          'max-w-[calc(100vw-2rem)]',
          'wj-frost',
          'border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
          'shadow-lg text-sm',
          'text-[var(--color-text-primary-light)] dark:text-[var(--color-text-primary-dark)]',
          'transition-all duration-300',
          open ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2',
          open && interactive ? 'pointer-events-auto' : 'pointer-events-none',
          className,
        )}
        {...props}
      >
        {busy ? (
          <span
            aria-hidden
            className="block h-4 w-4 shrink-0 animate-spin rounded-full border-2 border-[var(--color-accent-500)] border-t-transparent"
          />
        ) : (
          icon
        )}
        <span className="min-w-0">{children}</span>
        {detail != null && (
          <span aria-hidden className="shrink-0 tabular-nums">
            {detail}
          </span>
        )}
        {action}
        {onDismiss && (
          <button
            type="button"
            onClick={onDismiss}
            aria-label={dismissLabel}
            title={dismissLabel}
            className="wj-focus-ring p-1 -me-1 rounded-full text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)] hover:bg-[var(--color-warm-200)] dark:hover:bg-[var(--color-surface-muted-dark)] transition-colors"
          >
            {/* Inline X glyph: the DS stays icon-library-free (same documented
                exception as the Select caret). */}
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path
                d="M3.5 3.5l9 9m0-9l-9 9"
                stroke="currentColor"
                strokeWidth="1.8"
                strokeLinecap="round"
              />
            </svg>
          </button>
        )}
      </div>
    )
  },
)
Toast.displayName = 'Toast'

export { Toast }
